import {
  defaultTreeAdapter,
  html,
  parse,
  type DefaultTreeAdapterMap,
} from 'parse5';

export interface HeadElement {
  tagName: 'script' | 'base';
  id?: string;
  markup: string;
}

export const insertHtmlHeadElements = (
  source: string,
  elements: HeadElement[],
): string => {
  if (elements.length === 0) return source;
  const document = parse(source, { sourceCodeLocationInfo: true });
  const missingElements = new Set(elements);
  const pending: DefaultTreeAdapterMap['node'][] = [document];
  while (pending.length > 0) {
    const node = pending.pop();
    if (!node) break;
    if (
      defaultTreeAdapter.isElementNode(node) &&
      node.namespaceURI === html.NS.HTML
    ) {
      for (const element of missingElements) {
        if (
          node.tagName === element.tagName &&
          (element.id === undefined ||
            node.attrs.some(
              (attr) => attr.name === 'id' && attr.value === element.id,
            ))
        ) {
          missingElements.delete(element);
        }
      }
      if (missingElements.size === 0) return source;
    }
    if ('childNodes' in node) {
      pending.push(...node.childNodes);
    }
  }

  const root = document.childNodes
    .filter(defaultTreeAdapter.isElementNode)
    .find((node) => node.tagName === 'html');
  const head = root?.childNodes
    .filter(defaultTreeAdapter.isElementNode)
    .find((node) => node.tagName === 'head');
  const doctype = document.childNodes.find(
    defaultTreeAdapter.isDocumentTypeNode,
  );
  const insertAt =
    head?.sourceCodeLocation?.startTag?.endOffset ??
    root?.sourceCodeLocation?.startTag?.endOffset ??
    doctype?.sourceCodeLocation?.endOffset ??
    0;
  const markup = Array.from(missingElements, (element) => element.markup).join(
    '',
  );
  return source.slice(0, insertAt) + markup + source.slice(insertAt);
};
